package main

const modelPickerCSS = `
.target-bar>.model-picker-trigger{min-width:0;flex:1;justify-content:flex-start;gap:10px;background:var(--surface);border:1px solid var(--border);padding:12px 14px;border-radius:12px}
#model-picker-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;min-width:0}.model-picker-trigger kbd{margin-left:auto;color:var(--muted);font:inherit;font-size:.7rem;white-space:nowrap}
#model-picker{width:min(620px,calc(100% - 24px));max-height:calc(100dvh - 24px);padding:0;overflow:hidden}
#model-picker[open]{display:flex;flex-direction:column}.model-picker-head{display:flex;align-items:flex-start;gap:16px;padding:22px 22px 14px}.model-picker-head>div{flex:1;min-width:0}.model-picker-head h2{margin:0 0 6px;font-size:1.15rem}.model-picker-head p{font-size:.78rem;color:var(--muted);margin:0;line-height:1.5}.model-picker-head>button{flex:none;min-height:48px}
.model-picker-filters{padding:0 22px 14px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}.model-picker-search{grid-column:1/-1;display:flex;align-items:center;gap:8px;padding:0 12px;background:var(--surface);border:1px solid var(--border);border-radius:10px}.model-picker-search:focus-within{outline:2px solid var(--primary);outline-offset:2px}.model-picker-search>.icon{color:var(--muted);flex:none}.model-picker-search input{background:transparent;border:0;outline:none;min-width:0;padding:12px 0;box-shadow:none}.model-picker-filters>label{min-width:0;margin:0}.model-picker-filters>.check{white-space:nowrap;font-size:.8rem}
#model-picker-results{overflow:auto;overscroll-behavior:contain;min-height:100px;max-height:48dvh;border-block:1px solid var(--border);scroll-padding-block:8px}
.model-choice{display:flex;width:100%;align-items:center;gap:12px;min-height:72px;text-align:left;background:transparent;color:var(--ink);border:0;border-radius:0;padding:14px 22px;white-space:normal;border-bottom:1px solid var(--border)}.model-choice:last-child{border-bottom:0}.model-choice.highlighted{background:var(--accent)}.model-choice:hover{background:var(--surface)}.model-choice-body{display:grid;gap:5px;flex:1;min-width:0;overflow-wrap:anywhere}.model-choice-body>strong{display:flex;align-items:center;gap:6px;font-size:.94rem}.model-choice-body>span,.model-choice-body>small{font-size:.73rem;line-height:1.45;color:var(--muted)}.model-choice-current{flex:none;color:var(--primary)}.model-picker-empty{padding:30px 22px;text-align:center;color:var(--muted)}.model-picker-empty>.icon{width:28px;height:28px}.model-picker-empty h3{color:var(--ink);font-size:1rem}.model-picker-empty p{font-size:.8rem;line-height:1.7}
.model-picker-footer{display:flex;align-items:center;gap:10px;padding:12px 18px;flex-wrap:wrap}.model-picker-footer>span{margin-right:auto;color:var(--muted);font-size:.75rem}.model-picker-footer>button{min-height:48px;font-size:.8rem}.model-picker-more{margin:8px 22px;min-height:48px;flex:none}
@media(max-width:520px){.model-picker-trigger kbd{display:none}.model-picker-head{padding:16px 16px 12px}.model-picker-head h2{font-size:1.03rem}.model-picker-filters{padding:0 16px 12px;gap:10px}.model-choice{padding:14px 16px;gap:10px}.model-choice>.identity-avatar{width:32px;height:32px}.model-picker-footer{padding:10px 14px;gap:6px}.model-picker-footer>span{flex-basis:100%}#model-picker-results{max-height:43dvh}}
`
